-- Exercise catalog, part 2: ~150 common exercises with images, from free-exercise-db
-- (github.com/yuhonas/free-exercise-db, public domain / Unlicense, data originally from
-- wrkout/exercises.json, also Unlicense). Names and steps are Kova Health's own Spanish copy,
-- written from the source. Images are resized copies hosted in our own bucket (no hot-linking).
-- Generated; the 5 original exercises keep their coaching copy and only gain images.

values ('exercise-media', 'exercise-media', true, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

update public.exercises set media = $j$[{"kind": "image", "ref": "exercise-media/sentadilla/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/sentadilla/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb || media where owner_id is null and slug = 'sentadilla';






























update public.exercises set media = $j$[{"kind": "image", "ref": "exercise-media/peso-muerto/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/peso-muerto/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb || media where owner_id is null and slug = 'peso-muerto';



update public.exercises set media = $j$[{"kind": "image", "ref": "exercise-media/press-banca/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/press-banca/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb || media where owner_id is null and slug = 'press-banca';











































