insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'extension-cuadriceps', 'Extensión de cuádriceps', 'Extensión cuád.', 'strength', 'weight_reps', 'beginner', $j${"steps": ["Siéntate con la espalda apoyada y el rodillo sobre los tobillos.", "Ajusta la máquina para que la rodilla quede alineada con el eje.", "Extiende las piernas hasta arriba y aprieta los cuádriceps un segundo.", "Baja lento sin dejar que el peso golpee."]}$j$::jsonb, $j$[{"kind": "image", "ref": "exercise-media/extension-cuadriceps/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/extension-cuadriceps/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb);
