insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'peso-muerto-rumano', 'Peso muerto rumano', 'PM rumano', 'strength', 'weight_reps', 'intermediate', $j${"steps": ["Sostén la barra a la altura de la cadera, agarre al ancho de hombros, rodillas levemente flexionadas.", "Lleva la cadera atrás deslizando la barra por los muslos con la espalda neutra.", "Baja hasta sentir el estiramiento en los isquiotibiales, más o menos a media tibia.", "Vuelve empujando la cadera al frente y aprieta los glúteos arriba."]}$j$::jsonb, $j$[{"kind": "image", "ref": "exercise-media/peso-muerto-rumano/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/peso-muerto-rumano/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb);
