insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'peso-muerto-piernas-rigidas-mancuernas', 'Peso muerto con piernas rígidas (mancuernas)', 'PM rígidas manc.', 'strength', 'weight_reps', 'beginner', $j${"steps": ["Párate con una mancuerna en cada mano frente a los muslos.", "Con las rodillas casi rectas, inclínate desde la cadera bajando las mancuernas.", "Mantén la espalda recta y baja hasta sentir el estiramiento atrás de las piernas.", "Sube extendiendo la cadera."]}$j$::jsonb, $j$[{"kind": "image", "ref": "exercise-media/peso-muerto-piernas-rigidas-mancuernas/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/peso-muerto-piernas-rigidas-mancuernas/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb);
