insert into public.exercises (owner_id, slug, name, short_name, category, measurement_type, level, instructions, media) values (null, 'patada-gluteo', 'Patada de glúteo', 'Patada glúteo', 'strength', 'reps', 'beginner', $j${"steps": ["Apóyate en cuatro puntos, manos bajo los hombros y rodillas bajo la cadera.", "Lleva una pierna hacia atrás y arriba, con la rodilla flexionada y el pie hacia el techo.", "Aprieta el glúteo arriba sin arquear la zona lumbar.", "Vuelve con control. Completa y cambia de pierna."]}$j$::jsonb, $j$[{"kind": "image", "ref": "exercise-media/patada-gluteo/0.jpg", "license": "Unlicense", "source": "free-exercise-db"}, {"kind": "image", "ref": "exercise-media/patada-gluteo/1.jpg", "license": "Unlicense", "source": "free-exercise-db"}]$j$::jsonb);
